// Writes the catalog's index.json from a directory of static JSON files.
//
// Usage: npm run catalog -- <catalog-dir> [--stdout]
//
// The directory is the one served by caddy (or any static host) under the URL
// the app fetches (`VITE_CATALOG_URL`, default `<app>/catalog/`):
//
//   catalog/
//     index.json            <- generated by this script
//     locations.json
//     dates.json
//     abbreviations/*.json
//     timetables/**/*.json  plain Subject[], subdirectories allowed
//
// Every entry carries an 8-character hash, so the app only re-downloads what
// really changed. A timetable's hash is `Subjects.hash()` of its validated
// subjects, so the app matches a timetable by hash without downloading it; its
// name is its file name, so the index carries no other metadata.
//
// jiti loads the primitives' TypeScript directly, so the hash is computed by
// the very code the app checks it with.
import { readdir, readFile, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { parseArgs } from "node:util";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url);
const { shortHash, subjectsFileSchema, subjectsHash } = await jiti.import(
  "../src/lib/primitives/subject.ts",
);

const usage = "usage: npm run catalog -- <catalog-dir> [--stdout]\n";

let options;
try {
  options = parseArgs({
    allowPositionals: true,
    options: { stdout: { type: "boolean", default: false }, help: { type: "boolean", short: "h" } },
  });
} catch (error) {
  process.stderr.write(`${error.message}\n${usage}`);
  process.exit(1);
}
if (options.values.help) {
  process.stdout.write(usage);
  process.exit(0);
}
if (options.positionals.length !== 1) {
  process.stderr.write(usage);
  process.exit(1);
}
const toStdout = options.values.stdout;
const dir = options.positionals[0];

// Every `.json` below `sub`, subdirectories included, as paths relative to the
// catalog root.
async function jsonFiles(sub) {
  try {
    const entries = await readdir(path.join(dir, sub), { recursive: true, withFileTypes: true });
    return entries
      .filter((entry) => entry.isFile() && entry.name.endsWith(".json"))
      .map((entry) => path.relative(dir, path.join(entry.parentPath, entry.name)))
      .map((relative) => relative.split(path.sep).join("/"))
      .sort();
  } catch {
    // A missing subdirectory is normal: the catalog may serve only some kinds.
    return [];
  }
}

async function read(relative) {
  const file = path.join(dir, relative);
  const raw = await readFile(file, "utf8");
  // The file's mtime: the picker dialog shows it as the "last changed" of a
  // catalog row, so a user can tell an old file from a fresh one.
  const modified = (await stat(file)).mtime.toISOString();
  return { json: JSON.parse(raw), modified };
}

// A timetable: `Subjects.hash()` of what the app will read from the file, so
// defaults filled in by the schema count the same as written-out ones.
function timetableHash(json) {
  const parsed = subjectsFileSchema.safeParse(json);
  if (!parsed.success) throw new Error("not a list of subjects");
  return subjectsHash(parsed.data);
}

const files = [];

async function add(relative, kind, hashOf = shortHash) {
  try {
    const file = await read(relative);
    files.push({ path: relative, kind, hash: hashOf(file.json), modified: file.modified });
  } catch (error) {
    process.stderr.write(`skipped ${relative}: ${error.message}\n`);
  }
}

await add("locations.json", "locations");
// One dates file, like one locations file: the app holds a single
// `SemesterDates` and installs this one by itself.
await add("dates.json", "dates");
for (const relative of await jsonFiles("abbreviations")) await add(relative, "abbreviations");
for (const relative of await jsonFiles("timetables")) {
  await add(relative, "timetables", timetableHash);
}

const index = { version: 1, generated: new Date().toISOString(), files };
const text = JSON.stringify(index, null, 2) + "\n";

if (toStdout) process.stdout.write(text);
else {
  await writeFile(path.join(dir, "index.json"), text);
  process.stderr.write(`wrote ${path.join(dir, "index.json")} (${files.length} files)\n`);
}
